diffs.patch:
Index: opencode-studio/opencode.json
===================================================================
--- opencode-studio/opencode.json	
+++ opencode-studio/opencode.json	
@@ -1,18 +1,25 @@
 {
   "$schema": "https://opencode.ai/config.json",
   "instructions": ["CHARTER.md", ".ai/MEMORY.md"],
   "permission": {
     "*": "ask",
     "bash": {
       "*": "ask",
       "git *": "allow"
     }
   },
   "provider": {
     "ollama": {
       "npm": "@ai-sdk/openai-compatible",
       "options": { "baseURL": "http://localhost:11434/v1" },
       "models": { "llama3.2": { "name": "llama3.2 (local)" } }
     }
+  },
+  "agent": {
+    "builder": {
+      "description": "Primary agent for the Canvas Snapshot Diff Tool project.",
+      "mode": "primary",
+      "prompt": "{file:./system_prompt.txt}"
+    }
   }
 }

